def normalize_trainings(apps, schema_editor):
    Attempt = apps.get_model("recsys", "VariantAttempt")
    TimeLog = apps.get_model("recsys", "VariantTaskTimeLog")
    now = timezone.now()
    seen = set()
    # Newest started unfinished work wins; heartbeats must not determine the winner.
    for work in Attempt.objects.using(schema_editor.connection.alias).filter(mode="training").select_related(
        "assignment__template").order_by("-started_at", "-pk").iterator():
        key = (work.assignment.user_id, work.assignment.template.exam_version_id)
        if work.completed_at:
            work.legacy_completed_at = work.completed_at
            work.archived_at = work.archived_at or work.completed_at
            work.completed_at = None
        elif not work.archived_at:
            if key in seen:
                work.archived_at = now
            else:
                seen.add(key)
        if work.archived_at:
            if work.active_variant_task_id and work.active_started_at:
                stopped = max(work.active_started_at, min(now, max(work.active_started_at, work.last_seen_at or work.active_started_at) + timedelta(seconds=90)))
                TimeLog.objects.using(schema_editor.connection.alias).create(
                    variant_attempt_id=work.pk, variant_task_id=work.active_variant_task_id,
                    started_at=work.active_started_at, stopped_at=stopped,
                    duration=stopped-work.active_started_at, stop_reason="auto", auto_stopped=True,
                )
            work.active_variant_task_id = None
            work.active_started_at = None
            work.training_revision += 1
            work.save(using=schema_editor.connection.alias, update_fields=[
                "archived_at", "legacy_completed_at", "completed_at", "active_variant_task", "active_started_at", "training_revision",
            ])


